*** Begin Patch
*** Update File: /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/bluesky-ui-automation/UITests/UITests.swift
@@
     func testDismissAndInspect() {
         let bsky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
         bsky.activate()

-        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
-        let openButton = springboard.buttons["Open"]
-        if openButton.waitForExistence(timeout: 5) {
-            openButton.tap()
-        } else {
-            let appOpen = bsky.buttons["Open"]
-            if appOpen.exists { appOpen.tap() }
-        }
+        let likes = bsky.buttons.matching(
+            NSPredicate(format: "label CONTAINS[c] %@", "Likes")
+        ).firstMatch
+        if likes.waitForExistence(timeout: 5) {
+            likes.tap()
+        } else {
+            bsky.coordinate(withNormalizedOffset: CGVector(dx: 0.77, dy: 0.357)).tap()
+        }
         sleep(2)
     }
 }
*** End Patch

